Mesh<Point, double> extract_filaments(RT const &rt, double threshold) {
    Mesh<Point, double> mesh;
    // Lambda to test if a facet is "large" (i.e., all its three edges are longer than sqrt(threshold))
    auto is_large_facet = [&](RT::Facet const& f) -> bool {
        RT::Cell_handle c = f.first;
        unsigned k = f.second; // index of the opposite vertex, the facet consists of the other three vertices
        for (unsigned i = 0; i < 4; ++i) {
            if (i == k) continue;
            for (unsigned j = i + 1; j < 4; ++j) {
                if (j == k) continue;
                // Compute squared length of the edge between vertex i and vertex j
                if (rt.segment(c, i, j).squared_length() < threshold) {
                    return false;
                }
            }
        }
        return true;
    };
    // Iterate over all finite facets of the triangulation
    for (auto f = rt.finite_facets_begin(); f != rt.finite_facets_end(); ++f) {
        if (is_large_facet(*f)) {
            // Retrieve the three vertices of the facet
            std::array<RT::Vertex_handle, 3> verts;
            unsigned idx = 0;
            for (unsigned i = 0; i < 4; ++i) {
                if (i != f->second) {
                    verts[idx++] = rt.vertex(f->first, i);
                }
            }
            // Insert the three points into the mesh (using 0.0 as the associated double value)
            for (auto const& vh : verts) {
                mesh.insert(rt.point(vh), 0.0);
            }
        }
    }
    return mesh;
}

